+/// Every vertex of `facets` moved by `off`: a common model or WCS
+/// translation (the review of PR #3674).
+fn moved(facets: &[Triangle], off: [f64; 3]) -> Vec<Triangle> {
+    let at = |p: Point3| Point3::new(p.x + off[0], p.y + off[1], p.z + off[2]);
